    function destroyChart(id) {
        if (chartInstances[id]) {
            chartInstances[id].destroy();
            chartInstances[id] = null;
        }
    }

    function renderChart(id, options, emptyId) {
        var el = document.querySelector(id);
        var emptyEl = emptyId ? getEl(emptyId) : null;
        if (!el || typeof ApexCharts === "undefined") {
            return;
        }
        destroyChart(id);
        if (!options || options.isEmpty) {
            el.innerHTML = "";
            if (emptyEl) {
                emptyEl.className = "ssd-dash-chart-empty";
            }
            return;
        }
        if (emptyEl) {
            emptyEl.className = "ssd-dash-chart-empty d-none";
        }
        if (!options.responsive) {
            options.responsive = getChartResponsive();
        }
        if (window.DashboardChartUtils) {
            window.DashboardChartUtils.enhanceBarDataLabels(options);
        }
        chartInstances[id] = new ApexCharts(el, options);
        chartInstances[id].render();
    }

    function setScrollWrapHeight(wrapEl, itemCount, rowHeight) {
        if (!wrapEl) {
            return;
        }
        var maxHeight = 420;
        var minHeight = 280;
        var calculated = itemCount * rowHeight + 48;
        var height = calculated > maxHeight ? maxHeight : calculated;
        if (height < minHeight) {
            height = minHeight;
        }
        wrapEl.style.maxHeight = height + "px";
        wrapEl.style.overflowY = itemCount * rowHeight + 48 > maxHeight ? "auto" : "visible";
    }

    function setChartPreviewNote(noteId, totalCount, previewCount) {
        var noteEl = noteId ? getEl(noteId) : null;
        if (!noteEl) {
            return;
        }
        if (totalCount > previewCount) {
            noteEl.textContent = "Hiển thị Top " + previewCount + " / " + totalCount + " — bấm phóng to để xem toàn bộ.";
            noteEl.className = "ssd-dash-chart-note";
        } else {
            noteEl.textContent = "";
            noteEl.className = "ssd-dash-chart-note d-none";
        }
    }

    function sliceTopRows(rows, valueField, limit, desc) {
        var sorted = rows.slice(0);
        sorted.sort(function (a, b) {
            var va = parseFloat(a[valueField]) || 0;
            var vb = parseFloat(b[valueField]) || 0;
            return desc ? vb - va : va - vb;
        });
        return {
            items: limit && sorted.length > limit ? sorted.slice(0, limit) : sorted,
            total: sorted.length
        };
    }

    function buildVerticalCountOptions(labels, series, chartHeight, distributed, yTitle) {
        return {
            series: [{ name: "Quyết định", data: series}],
            chart: Object.assign({ height: chartHeight, type: "bar" }, baseChartOpts),
            plotOptions: {
                bar: {
                    borderRadius: 6,
                    columnWidth: labels.length > 8 ? "78%" : "55%",
                    distributed: distributed === true
                }
            },
            colors: distributed === true ? CHART_PALETTE : [BLUE],
            dataLabels: {
                enabled: true,
                formatter: function (val) { return formatNumber(val); },
                style: { colors: ["#fff"], fontSize: "10px", fontWeight: 600 }
            },
            xaxis: {
                categories: labels,
                labels: { rotate: labels.length > 6 ? -45 : 0, trim: true, style: { fontSize: "10px"} }
            },
            yaxis: {
                min: 0,
                title: { text: yTitle || "Số lượng" },
                labels: { formatter: function (val) { return formatNumber(val); } }
            },
