            "ssd-kpi-student": summary.DistinctStudent,
            "ssd-kpi-active": summary.ActiveSanction,
            "ssd-kpi-suspended": summary.SuspendedCount
        };
        var key;
        for (key in map) {
            if (!map.hasOwnProperty(key)) {
                continue;
