    function fetchDashboard() {
        var filters = getFiltersFromDom();
        var validationMsg = validateFilters(filters);
        if (validationMsg) {
            setErrorMessage(validationMsg);
            showState("error");
            return;
        }
        showState("loading");
        setButtonsLoading(true);
        setErrorMessage("");
        loadDashboardData(function (success, message, data) {
            setButtonsLoading(false);
            if (!success) {
                setErrorMessage(message);
                showState("error");
                return;
            }
            try {
                renderDashboard(data);
            } catch (ex) {
                setErrorMessage("Lỗi xử lý dữ liệu dashboard.");
                showState("error");
            }
        });
    }

    function openFullscreen(stateKey) {
        var overlay = getEl("ssdDashFullscreenOverlay");
        var titleEl = getEl("ssdDashFullscreenTitle");
        var chartWrap = getEl("ssdDashFullscreenChartWrap");
        var state = fullscreenStates[stateKey];
        var options;
        if (!overlay || !state || !state.optionsBuilder) {
            return;
        }
        ensureFullscreenOverlay();
        if (titleEl) {
            titleEl.textContent = state.title || "Biểu đồ chi tiết";
        }
        try {
            options = state.optionsBuilder();
        } catch (ex) {
            return;
        }
        if (chartWrap && options && options.chart) {
            chartWrap.style.height = options.chart.height + "px";
        }
        renderChart("#ssdDashChartPrimaryFullscreen", options, null);
        if (state.layoutMode === "line") {
            overlay.className = "ssd-dash-fullscreen ssd-dash-fullscreen-line";
        } else if (state.layoutMode === "center") {
            overlay.className = "ssd-dash-fullscreen ssd-dash-fullscreen-center";
        } else if (state.layoutMode === "vertical") {
            overlay.className = "ssd-dash-fullscreen ssd-dash-fullscreen-vertical";
        } else {
            overlay.className = "ssd-dash-fullscreen ssd-dash-fullscreen-horizontal";
        }
        document.body.style.overflow = "hidden";
        if (chartInstances["#ssdDashChartPrimaryFullscreen"]) {
            chartInstances["#ssdDashChartPrimaryFullscreen"].windowResizeHandler();
        }
    }

    function closeFullscreen() {
        var overlay = getEl("ssdDashFullscreenOverlay");
        var chartWrap = getEl("ssdDashFullscreenChartWrap");
        if (!overlay) {
            return;
        }
        overlay.className = "ssd-dash-fullscreen d-none";
        document.body.style.overflow = "";
        destroyChart("#ssdDashChartPrimaryFullscreen");
        if (chartWrap) {
            chartWrap.style.height = "";
        }
    }

    function bindEvents() {
        if (eventsBound) {
            return;
        }
        eventsBound = true;

        var btnLoad = getEl("ssdDashBtnLoad");
        var btnRefresh = getEl("ssdDashBtnRefresh");
        var btnClose = getEl("ssdDashBtnCloseFullscreen");

        if (btnLoad) {
            btnLoad.addEventListener("click", fetchDashboard);
        }
        if (btnRefresh) {
            btnRefresh.addEventListener("click", fetchDashboard);
        }
        if (btnClose) {
            btnClose.addEventListener("click", closeFullscreen);
        }
        bindFilterAutoReload();

        var fsButtons = [
            { id: "ssdDashBtnFullscreenByMonth", key: "byMonth" },
            { id: "ssdDashBtnFullscreenTrend", key: "trend" },
            { id: "ssdDashBtnFullscreenByForm", key: "byForm" },
            { id: "ssdDashBtnFullscreenByScience", key: "byScience" },
            { id: "ssdDashBtnFullscreenByCourse", key: "byCourse" },
            { id: "ssdDashBtnFullscreenByViolation", key: "byViolation" },
            { id: "ssdDashBtnFullscreenByClass", key: "byClass" }
        ];
        var i;
        resetFullscreenButtons();
        for (i = 0; i < fsButtons.length; i++) {
            (function (item) {
                var btn = getEl(item.id);
                if (btn) {
                    btn.addEventListener("click", function () {
                        if (btn.classList.contains("ssd-dash-fs-btn-inactive")) {
                            return;
                        }
                        openFullscreen(item.key);
                    });
                }
            })(fsButtons[i]);
        }

        document.addEventListener("keydown", function (e) {
            if (e.key === "Escape") {
                closeFullscreen();
            }
        });

        window.addEventListener("resize", function () {
            var key;
            for (key in chartInstances) {
                if (chartInstances.hasOwnProperty(key) && chartInstances[key]) {
                    chartInstances[key].windowResizeHandler();
                }
            }
        });
    }

    function initStudentSanctionDashboard() {
        if (!getEl("ssdDashContent")) {
            return;
        }
        ensureFullscreenOverlay();
        bindEvents();
        fetchDashboard();
    }

    function bootStudentSanctionDashboard() {
        if (document.readyState === "loading") {
            document.addEventListener("DOMContentLoaded", initStudentSanctionDashboard);
        } else {
            initStudentSanctionDashboard();
        }
    }

    bootStudentSanctionDashboard();
})();
